	@Test public void setupRejectsWrongAttemptChangedCaptureAndPotionViewThenCommitsExactReviewedBaseline() throws Exception
	{
		Source source=new Source();source.storage=store(1045);Worker worker=new Worker();Filepath root=Filepath.Unchecked.getRooted(temp.newFolder().toPath());BankRepository repo=new BankRepository(new BankRunCodec(SnapshotFixtures.gson()),SnapshotFixtures.codec());List<BankView> views=new ArrayList<>();BankController c=new BankController(source,repo,Runnable::run,views::add);c.start(()->root,worker);worker.runAll();source.observer.tick();c.tick();PotionCapture proof=views.get(views.size()-1).getCapture();
		try{c.startRun(true,new PotionCapture(SnapshotFixtures.CHARACTER_B,proof.getAttempt(),proof.getObservation()),false);worker.runAll();assertFalse(repo.load(root,source.character).isPresent());c.startRun(true,new PotionCapture(source.character,UUID.randomUUID(),proof.getObservation()),false);worker.runAll();assertFalse(repo.load(root,source.character).isPresent());source.fullBank=false;c.startRun(true,proof,false);worker.runAll();assertFalse(repo.load(root,source.character).isPresent());source.fullBank=true;source.captureValid=false;c.startRun(true,proof,false);worker.runAll();assertFalse(repo.load(root,source.character).isPresent());source.captureValid=true;c.startRun(false,proof,false);worker.runAll();assertFalse(repo.load(root,source.character).isPresent());c.startRun(true,proof,false);assertFalse(repo.load(root,source.character).isPresent());worker.runAll();BankRun saved=repo.load(root,source.character).get();assertEquals(proof.getObservation().getQuantities(),saved.getPotions().getInitial());assertTrue(saved.getRecent().get(0).getReason().contains("Complete current-setup"));assertEquals(1,saved.getInitialBank().quantity(SHIELD));}finally{c.stop();}
	}
