	@Test public void storedCorrectionsAreSignedAuditedAndDoNotReplayOrNotify() throws Exception
	{
		BankRun old=start(0,1045),corrected=BankEngine.correctStorage(old,TYPE,24,SnapshotFixtures.TIME);assertEquals(24,corrected.getPotions().balance(TYPE));try{BankEngine.reviewStorage(corrected,store(1045),Collections.singletonMap(TYPE,-Long.MAX_VALUE),session,SnapshotFixtures.TIME);fail("Overflowing manual adjustment must fail before commit");}catch(ArithmeticException expected){}assertEquals(old.getPotions().getInitial(),corrected.getPotions().getInitial());assertEquals(old.getInitialBank(),corrected.getInitialBank());assertEquals(old.getFinancial().getGainedGp(),corrected.getFinancial().getGainedGp());assertTrue(corrected.getRecent().get(0).getReason().contains("0 -> 24 doses; adjustment 24"));assertTrue(Overdrafts.between(old,corrected,true,id->"Potion").isEmpty());BankRun observed=move(corrected,P4,0,1045);assertEquals(24,observed.getPotions().balance(TYPE));BankRun debt=BankEngine.correctStorage(observed,TYPE,-3,SnapshotFixtures.TIME);assertEquals(3,Overdrafts.outstanding(new BankView(debt,null,Collections.emptyMap(),false,false,"")).get(0).getQuantity());assertTrue(Overdrafts.between(observed,debt,true,id->"Potion").isEmpty());BankRun paid=BankEngine.correctStorage(debt,TYPE,0,SnapshotFixtures.TIME);assertTrue(Overdrafts.outstanding(new BankView(paid,null,Collections.emptyMap(),false,false,"")).isEmpty());
	}
